import { createClient } from 'npm:@supabase/supabase-js@2';
import { authorizeSchoolCoach } from './authorize.ts';
import { inspectVideo } from '../technique-review-private/media.ts';
const MAX=25*1024*1024,BUCKET='technique-review';
const allowed=new Set(['https://duairlineseliteacademy.com','https://www.duairlineseliteacademy.com']);
const db=()=>createClient(Deno.env.get('SUPABASE_URL')!,Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!,{auth:{persistSession:false}});
Deno.serve(async req=>{
 const origin=req.headers.get('origin')||'';
 if(!allowed.has(origin))return new Response('Forbidden',{status:403});
 const headers={'access-control-allow-origin':origin,'access-control-allow-methods':'POST,OPTIONS','access-control-allow-headers':'content-type,apikey,x-du-session','content-type':'application/json','cache-control':'no-store'};
 const reply=(status:number,data:unknown)=>new Response(JSON.stringify(data),{status,headers});
 if(req.method==='OPTIONS')return new Response('',{headers});
 if(req.method!=='POST')return reply(405,{error:'Method not allowed'});


 try {
  const client=db(), token=req.headers.get('x-du-session')||'',body=await req.json();
  const scoped=await authorizeSchoolCoach(client,token,['athletes','context'].includes(body.action)?undefined:body.athleteId);
  const {cohort,athlete,session}=scoped;
  if(body.action==='context'){
      const weekNumber=Number(body.weekNumber);
      if(!Number.isInteger(weekNumber)||weekNumber<1||weekNumber>100)return reply(400,{error:'Invalid week'});
      const {data:week,error:weekError}=await client.from('programme_weeks').select('id,week_number').eq('programme_id',cohort.programme_id).eq('week_number',weekNumber).eq('status','live').maybeSingle();
      if(weekError||!week)return reply(409,{error:'No live programme week'});
      const {data:exercises,error:exerciseError}=await client.from('exercises').select('id,code,name').eq('active',true).order('display_order').limit(300);
      if(exerciseError)throw exerciseError;
      return reply(200,{weekId:week.id,weekNumber:week.week_number,exercises:exercises||[]});
    }
    if(body.action==='athletes'){
   const {data:athletes,error}=await client.from('athletes').select('id,full_name,display_name').eq('cohort_id',cohort.id).eq('athlete_type','school').eq('access_status','active').order('full_name').limit(100);
   if(error)throw error;
   return reply(200,{athletes:athletes||[]});
  }
  if(body.action==='list'){
   const {data,error}=await client.from('technique_video_requests').select('id,programme_week_id,exercise_id,instruction_override,status').eq('athlete_id',athlete.id).limit(40);
   if(error)throw error;
   return reply(200,{requests:data||[]});
  }
  if(body.action==='reserve'){
   const {data:week}=await client.from('programme_weeks').select('id').eq('id',body.weekId).eq('programme_id',cohort.programme_id).eq('status','live').maybeSingle();
   const {data:exercise}=await client.from('exercises').select('id').eq('id',body.exerciseId).eq('active',true).maybeSingle();
   if(!week||!exercise)return reply(403,{error:'Week or exercise unavailable'});
   if(body.requestId){
    const {data:requested}=await client.from('technique_video_requests').select('id,exercise_id').eq('id',body.requestId).eq('athlete_id',athlete.id).eq('programme_week_id',week.id).eq('status','open').maybeSingle();
    if(!requested||requested.exercise_id!==exercise.id)return reply(403,{error:'Video request mismatch'});
   }
   const {data:id,error:reservationError}=await client.rpc('reserve_technique_video_slot',{p_athlete_id:athlete.id,p_programme_week_id:week.id,p_uploaded_by:'school-coach:'+session.id,p_request_id:body.requestId||null,p_exercise_id:exercise.id});
   if(reservationError||!id)return reply(409,{error:'Weekly clip limit reached or reservation unavailable'});
   const path=athlete.id+'/'+week.id+'/'+id+'.mp4';
   const {data:upload,error:uploadError}=await client.storage.from(BUCKET).createSignedUploadUrl(path);
   if(uploadError||!upload){
    await client.from('technique_video_submissions').update({upload_state:'failed'}).eq('id',id);
    return reply(503,{error:'Video storage unavailable'});
   }
   const {error:markError}=await client.from('technique_video_submissions').update({object_key:path,upload_state:'uploading'}).eq('id',id);
   if(markError)return reply(503,{error:'Upload setup unavailable'});
   return reply(200,{id,path,token:upload.token,maxBytes:MAX,maxSeconds:15});
  }
  if(body.action==='finalize'){
   const {data:clip}=await client.from('technique_video_submissions').select('id,object_key,upload_state,reserved_until').eq('id',body.id).eq('athlete_id',athlete.id).maybeSingle();
   if(!clip||clip.upload_state!=='uploading'||Date.parse(clip.reserved_until)<=Date.now())return reply(409,{error:'Upload expired'});
   const {data:file,error:downloadError}=await client.storage.from(BUCKET).download(clip.object_key);
   if(downloadError||!file)return reply(409,{error:'Upload missing'});
   let durationMs:number;
   try {
    if(file.size<1||file.size>MAX)throw Error('Maximum video size is 25 MB');
    durationMs=inspectVideo(new Uint8Array(await file.arrayBuffer())).durationMs;
   } catch(e){
    await client.storage.from(BUCKET).remove([clip.object_key]);
    await client.from('technique_video_submissions').update({upload_state:'failed'}).eq('id',clip.id);
    return reply(400,{error:e instanceof Error?e.message:'Invalid video'});
   }
   const {error:saveError}=await client.from('technique_video_submissions').update({upload_state:'ready',duration_ms:durationMs,byte_size:file.size}).eq('id',clip.id).eq('upload_state','uploading');
   if(saveError)throw saveError;
   return reply(200,{ok:true,durationMs});
  }
  if(body.action==='playback'){
   const {data:clip}=await client.from('technique_video_submissions').select('object_key').eq('id',body.id).eq('athlete_id',athlete.id).eq('upload_state','ready').maybeSingle();
   if(!clip?.object_key)return reply(404,{error:'Video unavailable'});
   const {data:signed,error}=await client.storage.from(BUCKET).createSignedUrl(clip.object_key,60);
   if(error||!signed)return reply(503,{error:'Playback unavailable'});
   return reply(200,{url:signed.signedUrl,expiresInSeconds:60});
  }
  return reply(400,{error:'Unknown action'});
 }catch(e){
  console.error('Technique staff error',e);
  return reply(403,{error:'School code access or video request unavailable'});
 }
});

// Staff access is verified using the existing school-code session.
// This helper is for a service-role Edge Function only, never browser code.
export async function authorizeSchoolCoach(db: any, token: string, athleteId?: string) {
  if (!token || token.length < 16 || token.length > 256) throw Error('Session expired');
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(token));
  const hash = Array.from(new Uint8Array(digest), x => x.toString(16).padStart(2, '0')).join('');
  const { data: session } = await db.from('hub_sessions').select('id,role,staff_id,cohort_id,access_code_id,expires_at,revoked_at').eq('token_hash', hash).maybeSingle();
  if (!session || session.role !== 'staff' || session.revoked_at || Date.parse(session.expires_at) <= Date.now()) throw Error('Session expired');
  const { data: code } = await db.from('access_codes').select('status,code_type,cohort_id,staff_id,expires_at').eq('id', session.access_code_id).maybeSingle();
  if (!code || code.status !== 'active' || code.code_type !== 'staff' || code.cohort_id !== session.cohort_id || (code.expires_at && Date.parse(code.expires_at) <= Date.now())) throw Error('Access revoked');
  const { data: cohort } = await db.from('cohorts').select('id,programme_id,status').eq('id', session.cohort_id).maybeSingle();
  if (!cohort || cohort.status !== 'live' || !cohort.programme_id) throw Error('Cohort unavailable');
  // Existing school staff codes are cohort-scoped and may intentionally be shared.
  // If a code identifies an individual staff member, enforce their assignment too.
  if (code.staff_id) {
    const { data: assignment } = await db.from('staff_cohorts').select('staff_id').eq('staff_id', code.staff_id).eq('cohort_id', cohort.id).maybeSingle();
    if (!assignment) throw Error('Coach not assigned');
  }
  let athlete = null;
  if (athleteId) {
    const { data } = await db.from('athletes').select('id,cohort_id,access_status').eq('id', athleteId).eq('cohort_id', cohort.id).eq('access_status', 'active').maybeSingle();
    if (!data) throw Error('Athlete not in assigned cohort');
    athlete = data;
  }
  return { session, cohort, athlete };
}

// ISO BMFF/QuickTime duration validator. Rejects malformed/fragmented files.
export function inspectVideo(bytes: Uint8Array): {durationMs:number; format:string} {
  if (bytes.length < 32) throw Error('Invalid video');
  const d = new DataView(bytes.buffer, bytes.byteOffset, bytes.byteLength);
  const u32 = (p:number) => d.getUint32(p);
  const tag = (p:number) => String.fromCharCode(...bytes.subarray(p,p+4));
  let brand='', movie=false, fragmented=false;
  const durations:number[]=[];
  function boxes(start:number,end:number,depth:number):void {
    if(depth>8)throw Error('Invalid container');
    let p=start;
    while(p+8<=end) {
      let size=u32(p), head=8; const kind=tag(p+4);
      if(size===1) {
        if(p+16>end)throw Error('Invalid box');
        const high=u32(p+8);if(high!==0)throw Error('Oversized box');
        size=u32(p+12);head=16;
      } else if(size===0)size=end-p;
      if(size<head || p+size>end)throw Error('Malformed box');
      if(kind==='ftyp'){if(size<16)throw Error('Invalid ftyp');brand=tag(p+head);}
      if(kind==='moof')fragmented=true;
      if(kind==='moov')movie=true;
      if(kind==='mvhd'||kind==='mdhd') {
        const q=p+head,version=bytes[q];
        if(version!==0&&version!==1)throw Error('Unsupported media version');
        const offset=kind==='mvhd'?(version===1?20:12):(version===1?20:12);
        const at=q+offset,need=version===1?12:8;
        if(at+need>p+size)throw Error('Truncated duration');
        const scale=u32(at);
        const ticks=version===1?u32(at+4)*4294967296+u32(at+8):u32(at+4);
        if(scale===0||!Number.isSafeInteger(ticks))throw Error('Invalid duration');
        durations.push(ticks*1000/scale);
      }
      if(['moov','trak','mdia'].includes(kind))boxes(p+head,p+size,depth+1);
      p+=size;
    }
    if(p!==end)throw Error('Invalid trailing bytes');
  }
  boxes(0,bytes.length,0);
  if(!brand||!movie||fragmented||durations.length===0)throw Error('Unsupported video container');
  const durationMs=Math.ceil(Math.max(...durations));
  if(durationMs<1||durationMs>15000)throw Error('Video must be 15 seconds or shorter');
  return {durationMs,format:brand};
}
